/**
 * W0_MODULE_GUARD — Shared entitlement & module gate
 *
 * Called by every workflow entrypoint to validate:
 * 1. Module is enabled globally
 * 2. Tenant has active entitlement (if multi-tenant)
 * 3. Required env vars are present
 * 4. Module hasn't expired
 *
 * Input (from calling workflow):
 *   - module_key: string (e.g. 'channel_whatsapp', 'delivery_dispatch')
 *   - tenant_id: string (optional, defaults to $env.DEFAULT_TENANT_ID)
 *
 * Output:
 *   - allowed: boolean
 *   - reason: string (if denied)
 *   - config_overrides: object (tenant-specific config, if any)
 */

const moduleKey = $input.first().json.module_key;
const tenantId = $input.first().json.tenant_id || $env.DEFAULT_TENANT_ID || 'default';

if (!moduleKey) {
  return [{ json: { allowed: false, reason: 'GUARD_ERROR: module_key not provided' } }];
}

// 1. Check global module enablement via Strapi
const strapiBase = $env.STRAPI_API_URL || 'http://strapi:1337';
const strapiToken = $env.STRAPI_API_TOKEN_INTERNAL;

try {
  // Fetch module definition
  const moduleRes = await fetch(
    `${strapiBase}/api/product-modules?filters[key][$eq]=${moduleKey}`,
    { headers: { 'Authorization': `Bearer ${strapiToken}` } }
  );
  const moduleData = await moduleRes.json();
  const mod = moduleData?.data?.[0];

  if (!mod) {
    return [{ json: { allowed: false, reason: `MODULE_NOT_FOUND: ${moduleKey}` } }];
  }

  // shared_core modules are always allowed
  if (mod.tier === 'shared_core' || mod.enabled_globally === true) {
    return [{ json: { allowed: true, reason: 'GLOBAL_ENABLED', config_overrides: {} } }];
  }

  // 2. Check tenant entitlement
  const entRes = await fetch(
    `${strapiBase}/api/tenant-entitlements?filters[tenant_id][$eq]=${tenantId}&filters[module_key][$eq]=${moduleKey}&filters[enabled][$eq]=true`,
    { headers: { 'Authorization': `Bearer ${strapiToken}` } }
  );
  const entData = await entRes.json();
  const ent = entData?.data?.[0];

  if (!ent) {
    return [{ json: { allowed: false, reason: `NO_ENTITLEMENT: tenant=${tenantId} module=${moduleKey}` } }];
  }

  // 3. Check expiry
  if (ent.expires_at && new Date(ent.expires_at) < new Date()) {
    return [{ json: { allowed: false, reason: `EXPIRED: tenant=${tenantId} module=${moduleKey} expired=${ent.expires_at}` } }];
  }

  // 4. Return with config overrides
  return [{ json: {
    allowed: true,
    reason: 'ENTITLED',
    config_overrides: ent.config_overrides || {},
    tenant_id: tenantId,
    module_key: moduleKey
  } }];

} catch (err) {
  // On guard failure, switch to fail-closed for production security
  return [{ json: {
    allowed: false,
    reason: `GUARD_ERROR_FAILCLOSED: ${err.message}`,
    config_overrides: {}
  } }];
}
